import React, { useEffect, useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import ProfileHeader from "../../components/common/ProfileHeader";
import LoyaltyTile from "../../components/common/LoyaltyTile";
import TextBox from "../../components/common/TextBox";
import Button from "../../components/common/Button";

/* ---- Styled Wrappers ---- */
const PageWrapper = styled.div`
  background-color: ${({ theme }) => theme.colors.background};
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentContainer = styled.div`
  width: 100%;
  max-width: 900px;
  padding: 24px;
  box-sizing: border-box;
`;

const SectionTitle = styled.h2`
  color: ${({ theme }) => theme.colors.secondary}; /* FIXED */
  font-size: 20px;
  margin-bottom: 12px;
`;

const Card = styled.div`
  padding: 20px;
  background: white;
  border-radius: 16px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.07);
  margin-bottom: 20px;
`;

const LoyaltyList = styled.div`
  display: flex;
  flex-direction: column;
  gap: 16px;
`;

const LogoutButton = styled.button`
  margin-top: 20px;
  padding: 12px 20px;
  border-radius: 12px;
  background-color: ${({ theme }) => theme.colors.primary}; /* FIXED */
  color: white;
  border: none;
  font-size: 16px;
  cursor: pointer;
`;

/* ---- Logout Popup ---- */
const PopupOverlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.35);
  display: flex;
  justify-content: center;
  align-items: center;
`;

const PopupContainer = styled.div`
  width: 80%;
  max-width: 360px;
  background: white;
  border-radius: 18px;
  padding: 24px;
  text-align: center;
`;

const PopupTitle = styled.h3`
  font-size: 20px;
  margin-bottom: 10px;
`;

const PopupDesc = styled.p`
  color: #555;
  margin-bottom: 20px;
`;

const PopupButtonRow = styled.div`
  display: flex;
  justify-content: space-between;
  gap: 12px;
`;

const PopupButton = styled.button<{ primary?: boolean }>`
  flex: 1;
  padding: 12px;
  border-radius: 10px;
  border: ${({ primary }) => (primary ? "none" : "1px solid #ccc")};
  background: ${({ primary, theme }) =>
    primary ? theme.colors.primary : "#eee"}; /* FIXED */
  color: ${({ primary }) => (primary ? "white" : "#333")};
  cursor: pointer;
`;

const Profile: React.FC = () => {
  const [customer, setCustomer] = useState<any>(null);
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [showLogoutPopup, setShowLogoutPopup] = useState(false);

  /* NEW: loyalty programs */
  const [loyaltyPrograms, setLoyaltyPrograms] = useState<any[]>([]);

  /* -------------------------------------------------------------------
     LOAD PROFILE + LOYALTY PROGRAMS
  ------------------------------------------------------------------- */
  useEffect(() => {
    const stored = localStorage.getItem("customer");
    if (stored) {
      const data = JSON.parse(stored);
      setCustomer(data);
      setFirstName(data.firstName);
      setLastName(data.lastName);
      setEmail(data.email);
    }

    const token = localStorage.getItem("customerToken");
    if (!token) return;

    // Fetch profile
    fetch("http://localhost:5000/api/customers/me", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then(res => res.json())
      .then(data => {
        setCustomer(data);
        setFirstName(data.firstName);
        setLastName(data.lastName);
        setEmail(data.email);
        localStorage.setItem("customer", JSON.stringify(data));
      });

    // Fetch loyalty programs
    fetch("http://localhost:5000/api/loyalty/customer/me", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then(res => res.json())
      .then(entries => {
        if (Array.isArray(entries)) setLoyaltyPrograms(entries);
      });
  }, []);

  /* -------------------------------------------------------------------
     LOGOUT
  ------------------------------------------------------------------- */
  const handleLogout = () => {
    localStorage.removeItem("customer");
    localStorage.removeItem("customerToken");
    window.location.href = "/customer/login";
  };

  return (
    <>
      <PageWrapper>
        <ContentContainer>
          {/* FIXED PROFILE HEADER */}
          <ProfileHeader
            type="customer"
            name={`${firstName} ${lastName}`} /* FIXED */
            stat1={loyaltyPrograms.length}
            stat2={0}
            stat3={0}
          />

          {/* Loyalty programs */}
          <Card>
            <SectionTitle>My Loyalty Programs</SectionTitle>
            <LoyaltyList>
              {loyaltyPrograms.length === 0 ? (
                <div style={{ color: "#999" }}>No loyalty programs yet</div>
              ) : (
                loyaltyPrograms.map(entry => (
                  <LoyaltyTile
                    key={entry._id}
                    name={entry.business?.name}
                    location={
                      entry.business?.address ||
                      entry.business?.location ||
                      ""
                    }
                    rating={entry.business?.rating || 4.9}
                    reviews={entry.business?.reviewsCount || 0}
                    offer={entry.business?.loyalty?.rewardDescription || "Reward"}
                    filledCircles={entry.points}
                    totalCircles={entry.business?.loyalty?.rewardThreshold || 5}
                  />
                ))
              )}
            </LoyaltyList>
          </Card>

          <LogoutButton onClick={() => setShowLogoutPopup(true)}>
            Logout
          </LogoutButton>
        </ContentContainer>

        <TabBar type="customer" /> {/* FIXED */}
      </PageWrapper>

      {showLogoutPopup && (
        <PopupOverlay>
          <PopupContainer>
            <PopupTitle>Log Out</PopupTitle>
            <PopupDesc>Are you sure you want to log out?</PopupDesc>

            <PopupButtonRow>
              <PopupButton onClick={() => setShowLogoutPopup(false)}>
                Cancel
              </PopupButton>
              <PopupButton primary onClick={handleLogout}>
                Log Out
              </PopupButton>
            </PopupButtonRow>
          </PopupContainer>
        </PopupOverlay>
      )}
    </>
  );
};

export default Profile;
